Generated Query:
PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?premiumAmount
       (COUNT(DISTINCT ?claim) AS ?numberOfClaims)
       (SUM(?claimTotalLoss) AS ?totalLoss)
       ((SUM(?claimTotalLoss) / ?premiumAmount) AS ?lossRatio)
WHERE {
  SERVICE <mapped> {
    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .

    ?policy in:policyNumber ?policyNumber .

    ?premium in:premiumAmount ?premiumAmount .

    ?claim a in:Claim ;
           in:against ?coverage .

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?lossPaymentSum)
      WHERE {
        ?claim in:hasLossPayment ?lp .
        ?lp in:lossPaymentAmount ?v .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?lossReserveSum)
      WHERE {
        ?claim in:hasLossReserve ?lr .
        ?lr in:lossReserveAmount ?v .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?expensePaymentSum)
      WHERE {
        ?claim in:hasExpensePayment ?ep .
        ?ep in:expensePaymentAmount ?v .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?expenseReserveSum)
      WHERE {
        ?claim in:hasExpenseReserve ?er .
        ?er in:expenseReserveAmount ?v .
      }
      GROUP BY ?claim
    }

    BIND(
      COALESCE(?lossPaymentSum, 0) +
      COALESCE(?lossReserveSum, 0) +
      COALESCE(?expensePaymentSum, 0) +
      COALESCE(?expenseReserveSum, 0)
      AS ?claimTotalLoss
    )
  }
}
GROUP BY ?policyNumber ?premiumAmount
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolder (SUM(?amount) AS ?totalPremiumPaid)
WHERE {
  SERVICE <mapped> {
    ?policy in:hasPolicyHolder ?policyHolder ;
            in:policyNumber ?policyNumber .
    ?coverage in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .
    ?premium in:premiumAmount ?amount .
  }
}
GROUP BY ?policyHolder

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent .
    ?agent in:agentId ?agentId .
  }
}
GROUP BY ?agentId
ORDER BY ?agentId

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?openDate ?closeDate
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .
    OPTIONAL { ?claim in:claimOpenDate ?openDate . }
    OPTIONAL { ?claim in:claimCloseDate ?closeDate . }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber
       (COALESCE(SUM(DISTINCT ?lossPaymentAmt), 0) +
        COALESCE(SUM(DISTINCT ?lossReserveAmt), 0) +
        COALESCE(SUM(DISTINCT ?expensePaymentAmt), 0) +
        COALESCE(SUM(DISTINCT ?expenseReserveAmt), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment in:lossPaymentAmount ?lossPaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve in:lossReserveAmount ?lossReserveAmt .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment in:expensePaymentAmount ?expensePaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve in:expenseReserveAmount ?expenseReserveAmt .
    }
  }
}
GROUP BY ?claimNumber
ORDER BY ?claimNumber
